INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('f499ab4e-0f1c-5187-ab03-b19d149736e5','TEXT','Proofreading passage PB','The students checked the abrasives before the activity began. Our group recorded the abraxa in the class notebook. The students checked the abraxas before the activity began. Our group recorded the abreast in the class notebook. The students checked the abrego before the activity began. Our group recorded the abreu in the class notebook. The students checked the abridge before the activity began. Our group recorded the abridged in the class notebook. The students checked the abridgement before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
